package ganymedes01.etfuturum;

import java.io.*;
import java.util.*;
import net.minecraft.block.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.EntityLiving;
import net.minecraft.init.Blocks;
import net.minecraft.inventory.IInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.*;
import net.minecraft.tileentity.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.*;
import net.minecraft.world.gen.structure.StructureBoundingBox;

/** Immutable released geometry; native states, processors, inventories and entity admission own placement. */
final class StructureTemplate {
    private static final Map<String,StructureTemplate> CACHE=new HashMap<>();
    private static final ThreadLocal<Integer> PLACING=new ThreadLocal<>();
    final String name;final int sx,sy,sz;
    final NBTTagList blocks;
    final List<NBTTagCompound> connectors=new ArrayList<>();
    final List<String> names=new ArrayList<>();
    private final List<Map<String,String>> properties=new ArrayList<>();
    private final IBlockState[][] states;
    private final NBTTagList entities;
    private boolean supported=true;
    static StructureTemplate get(String name){return CACHE.computeIfAbsent(name,StructureTemplate::new);}
    static boolean placing(){return PLACING.get()!=null;}
    private StructureTemplate(String name){this.name=name;NBTTagCompound data;try(InputStream input=StructureTemplate.class.getResourceAsStream("/data/structure/"+name+".nbt")){if(input==null)throw new IOException("Missing released template "+name);data=CompressedStreamTools.readCompressed(input);}catch(IOException failure){throw new IllegalStateException(failure);}NBTTagList size=data.getTagList("size",3);sx=size.getIntAt(0);sy=size.getIntAt(1);sz=size.getIntAt(2);blocks=data.getTagList("blocks",10);entities=data.getTagList("entities",10);NBTTagList palette=data.getTagList("palette",10);if(palette.isEmpty()&&data.hasKey("palettes",9))palette=(NBTTagList)data.getTagList("palettes",9).get(0);states=new IBlockState[4][palette.tagCount()];for(int i=0;i<palette.tagCount();i++){NBTTagCompound entry=palette.getCompoundTagAt(i);names.add(entry.getString("Name"));Map<String,String> props=new HashMap<>();NBTTagCompound values=entry.getCompoundTag("Properties");for(String key:values.getKeySet())props.put(key,values.getString(key));properties.add(Collections.unmodifiableMap(props));for(int r=0;r<4;r++){states[r][i]=state(names.get(i),props,r);if(states[r][i]==null)supported=false;}}for(int i=0;i<blocks.tagCount();i++){NBTTagCompound entry=blocks.getCompoundTagAt(i);if(names.get(entry.getInteger("state")).equals("minecraft:jigsaw")){connectors.add(entry);String end=entry.getCompoundTag("nbt").getString("final_state");if(!end.isEmpty()&&state(end,Collections.emptyMap(),0)==null)supported=false;}}}
    boolean available(){return supported;}
    static BlockPos rotate(int x,int y,int z,int rotation){switch(rotation&3){case 1:return new BlockPos(-z,y,x);case 2:return new BlockPos(-x,y,-z);case 3:return new BlockPos(z,y,-x);default:return new BlockPos(x,y,z);}}
    static BlockPos position(NBTTagCompound entry,int rotation){NBTTagList pos=entry.getTagList("pos",3);return rotate(pos.getIntAt(0),pos.getIntAt(1),pos.getIntAt(2),rotation);}
    static BlockPos position(NBTTagCompound entry,int rotation,int mirror){if(mirror!=0)throw new IllegalArgumentException("Mirroring is not used by the retained trail layouts");return position(entry,rotation);}
    BlockPos direction(NBTTagCompound connector,int rotation,boolean top){String[] orientation=properties.get(connector.getInteger("state")).get("orientation").split("_");return direction(orientation[top?1:0],rotation);}
    BlockPos front(NBTTagCompound connector,int rotation){return direction(connector,rotation,false);}
    BlockPos top(NBTTagCompound connector,int rotation){return direction(connector,rotation,true);}
    private static BlockPos direction(String name,int rotation){EnumFacing facing=EnumFacing.byName(name);if(facing==null)throw new IllegalArgumentException("Invalid connector direction "+name);return rotate(facing.getXOffset(),facing.getYOffset(),facing.getZOffset(),rotation);}
    StructureBoundingBox box(int x,int y,int z,int rotation){BlockPos end=rotate(sx-1,sy-1,sz-1,rotation);return new StructureBoundingBox(x+Math.min(0,end.getX()),y,z+Math.min(0,end.getZ()),x+Math.max(0,end.getX()),y+sy-1,z+Math.max(0,end.getZ()));}
    StructureBoundingBox box(int x,int y,int z,int rotation,int mirror){if(mirror!=0)throw new IllegalArgumentException("Unsupported trail mirror");return box(x,y,z,rotation);}
    static IBlockState state(String name,Map<String,String> properties,int rotation){return ModernStates.structure(name,properties,rotation);}
    static IBlockState state(String name,Map<String,String> properties){return state(name,properties,0);}
    void place(World world,int x,int y,int z,int rotation,StructureBoundingBox clip,long seed,String processors){place(world,x,y,z,rotation,clip,seed,processors,null);}
    void place(World world,int x,int y,int z,int rotation,StructureBoundingBox clip,long seed,String processors,TrailProcessors.Result trail){
        if(!supported)throw new IllegalStateException("Unavailable structure palette "+name);Integer previous=PLACING.get();PLACING.set(previous==null?1:previous+1);
        try{for(int pass=0;pass<2;pass++)for(int i=0;i<blocks.tagCount();i++){NBTTagCompound entry=blocks.getCompoundTagAt(i),nbt=entry.getCompoundTag("nbt");int index=entry.getInteger("state");String id=names.get(index);if(id.equals("minecraft:structure_block")||id.equals("minecraft:structure_void"))continue;IBlockState state=states[rotation][index];if(id.equals("minecraft:jigsaw")){id=nbt.getString("final_state");if(id.equals("minecraft:structure_void"))continue;state=state(id.isEmpty()?"minecraft:air":id,Collections.emptyMap(),rotation);}if(state==null)continue;Block block=state.getBlock();boolean attached=block instanceof BlockTorch||block instanceof BlockChest||block instanceof BlockBanner||block instanceof BlockFlowerPot||block instanceof BlockLadder||block instanceof BlockVine;if(attached!=(pass==1))continue;BlockPos local=position(entry,rotation),pos=local.add(x,y,z);if(!clip.isVecInside(pos)||!world.isBlockLoaded(pos)||world.getBlockState(pos).getBlock()==Blocks.BEDROCK)continue;Random random=new Random(seed^(long)pos.getX()*3129871L^(long)pos.getZ()*116129781L^pos.getY());if(name.startsWith("bastion/")){long raw=(long)pos.getX()*3129871L^(long)pos.getZ()*116129781L^pos.getY();random.setSeed((raw*raw*42317861L+raw*11L)>>16^seed);state=BastionProcessors.apply(processors,id,state,rotation,random,local.getY());}else if(name.startsWith("ancient_city/")||name.startsWith("trial_chambers/"))state=UndergroundProcessors.apply(processors,id,state,rotation,random);else if(name.startsWith("trail_ruins/")){if(state.getBlock()==Blocks.AIR||id.equals("minecraft:jigsaw"))continue;if(trail!=null&&trail.states[i]!=null)state=trail.states[i].withRotation(Rotation.values()[rotation]);}if(state==null)continue;world.setBlockState(pos,state,18);TileEntity tile=world.getTileEntity(pos);if(tile!=null){if(tile instanceof TileEntityBed&&id.endsWith("_bed")){String color=id.substring(10,id.length()-4);if(color.equals("light_gray"))color="silver";for(net.minecraft.item.EnumDyeColor dye:net.minecraft.item.EnumDyeColor.values())if(dye.getName().equals(color))((TileEntityBed)tile).setColor(dye);}if(tile instanceof TileEntitySkull){TileEntitySkull skull=(TileEntitySkull)tile;skull.setType(0);String angle=properties.get(index).get("rotation");if(angle!=null)skull.setSkullRotation((Integer.parseInt(angle)+rotation*4)&15);}if(tile instanceof TileEntityFlowerPot&&id.startsWith("minecraft:potted_")){String plant=id.substring(17);NBTTagCompound plantTag=new NBTTagCompound();plantTag.setString("Name","minecraft:"+plant);IBlockState plantState=ModernStates.read(plantTag);if(plantState!=null)((TileEntityFlowerPot)tile).setItemStack(new ItemStack(plantState.getBlock(),1,plantState.getBlock().getMetaFromState(plantState)));}if(tile instanceof DecoratedPotTile&&nbt.hasKey("sherds",9)){NBTTagCompound saved=tile.writeToNBT(new NBTTagCompound());saved.setTag("sherds",nbt.getTag("sherds").copy());tile.readFromNBT(saved);}if(tile instanceof TrialSpawnerTile&&nbt.hasKey("normal_config",8))((TrialSpawnerTile)tile).configure(nbt.getString("normal_config"));if(tile instanceof BrushableTile&&trail!=null&&trail.loot[i]!=null)((BrushableTile)tile).configure(trail.loot[i],random.nextLong());if(tile instanceof LecternTile)((LecternTile)tile).template(nbt);if(tile instanceof IInventory){if(name.startsWith("pillager_outpost/")&&tile instanceof TileEntityLockableLoot)((TileEntityLockableLoot)tile).setLootTable(new ResourceLocation(UAB.ID,"chests/pillager_outpost"),random.nextLong());else inventory(world,(IInventory)tile,nbt,random);}if(tile instanceof TileEntityMobSpawner&&!(tile instanceof TrialSpawnerTile))((TileEntityMobSpawner)tile).getSpawnerBaseLogic().setEntityId(new ResourceLocation(name.startsWith("bastion/")?"magma_cube":"spider"));if(tile instanceof TileEntityBanner&&name.startsWith("pillager_outpost/"))ominousBanner((TileEntityBanner)tile);tile.markDirty();}}
            if(name.startsWith("bastion/")&&Features.enabled("entities.enableNetherMobs"))for(int i=0;i<entities.tagCount();i++){NBTTagCompound entry=entities.getCompoundTagAt(i);NBTTagList raw=entry.getTagList("pos",6);BlockPos local=rotate((int)Math.floor(raw.getDoubleAt(0)),(int)Math.floor(raw.getDoubleAt(1)),(int)Math.floor(raw.getDoubleAt(2)),rotation),pos=local.add(x,y,z);if(!clip.isVecInside(pos)||!world.isBlockLoaded(pos))continue;String id=entry.getCompoundTag("nbt").getString("id");Class<? extends EntityLiving> type=id.equals("minecraft:piglin_brute")?ganymedes01.etfuturum.entities.EntityPiglinBrute.class:id.equals("minecraft:piglin")?ganymedes01.etfuturum.entities.EntityPiglin.class:id.equals("minecraft:hoglin")?ganymedes01.etfuturum.entities.EntityHoglin.class:null;if(type==null||!MobRegistry.enabled(type))continue;try{EntityLiving mob=type.getConstructor(World.class).newInstance(world);mob.setLocationAndAngles(pos.getX()+.5,pos.getY(),pos.getZ()+.5,rotation*90,0);mob.onInitialSpawn(world.getDifficultyForLocation(pos),null);mob.enablePersistence();world.spawnEntity(mob);}catch(ReflectiveOperationException failure){throw new IllegalStateException(type.getName(),failure);}}
        }finally{if(previous==null)PLACING.remove();else PLACING.set(previous);}
    }
    private static void inventory(World world,IInventory inventory,NBTTagCompound data,Random random){if(data.hasKey("LootTable",8)){ResourceLocation table=new ResourceLocation(UAB.ID,data.getString("LootTable").replace("minecraft:",""));if(inventory instanceof TileEntityLockableLoot)((TileEntityLockableLoot)inventory).setLootTable(table,random.nextLong());else if(world instanceof WorldServer)for(ItemStack stack:ModernLoot.roll(table.getPath(),random,(WorldServer)world))insert(inventory,stack,random);}else{NBTTagList items=data.getTagList("Items",10);for(int i=0;i<items.tagCount();i++){NBTTagCompound entry=items.getCompoundTagAt(i);int slot=entry.getByte("Slot")&255;ItemStack stack=ModernLoot.item(entry.getString("id"));if(slot<inventory.getSizeInventory()&&!stack.isEmpty()){stack.setCount(Math.max(1,entry.hasKey("count")?entry.getInteger("count"):entry.getInteger("Count")));inventory.setInventorySlotContents(slot,stack);}}}}
    private static void insert(IInventory inventory,ItemStack stack,Random random){List<Integer> slots=new ArrayList<>();for(int i=0;i<inventory.getSizeInventory();i++)if(inventory.getStackInSlot(i).isEmpty())slots.add(i);if(!slots.isEmpty())inventory.setInventorySlotContents(slots.get(random.nextInt(slots.size())),stack);}
    private static void ominousBanner(TileEntityBanner banner){NBTTagCompound tag=banner.writeToNBT(new NBTTagCompound());tag.setInteger("Base",15);NBTTagList patterns=new NBTTagList();String[] names={"mr","bs","cs","bo","ms","hh","mc","bo"};int[] colors={9,8,7,8,15,8,8,15};for(int i=0;i<names.length;i++){NBTTagCompound pattern=new NBTTagCompound();pattern.setString("Pattern",names[i]);pattern.setInteger("Color",15-colors[i]);patterns.appendTag(pattern);}tag.setTag("Patterns",patterns);banner.readFromNBT(tag);}
}
